  const map = new Map();
  map.set(0, -1);
  let remainder = 0;

  for (let i = 0; i < nums.length; i++) {
    remainder = (remainder + nums[i]) % k;
    if (map.has(remainder)) {
      if (i - map.get(remainder) >= 2) {
        return true;
      }
    } else {
      map.set(remainder, i);
    }
